select part_code, part_shrt_name, sum(qnty_prev_year_2)/1000 as prev_year_2, sum(qnty_prev_year_1)/1000 as prev_year_1, sum(qnty_mnth_7)/1000 as month_7, sum(qnty_mnth_8)/1000 as month_8, sum(qnty_mnth_9)/1000 as month_9, sum(qnty_mnth_10)/1000 as month_10, sum(qnty_mnth_11)/1000 as month_11, sum(qnty_mnth_12)/1000 as month_12 from (select EVNT_DATE, PART_SHRT_NAME, PART_CODE, QNTY_1, LINE_SIGN, line_qnty, CASE WHEN EVNT_DATE >= TRUNC(ADD_MONTHS(SYSDATE, -24), 'YYYY') AND EVNT_DATE <= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), -12) -1 THEN line_qnty ELSE 0 END AS qnty_prev_year_2, CASE WHEN EVNT_DATE >= TRUNC(ADD_MONTHS(SYSDATE, -12), 'YYYY') AND EVNT_DATE <= TRUNC(SYSDATE, 'YYYY') - 1 THEN line_qnty ELSE 0 END AS qnty_prev_year_1, CASE WHEN TRUNC(EVNT_DATE, 'MM') = TRUNC(ADD_MONTHS(SYSDATE, -14), 'MM') THEN line_qnty ELSE 0 END AS qnty_mnth_7, CASE WHEN TRUNC(EVNT_DATE, 'MM') = TRUNC(ADD_MONTHS(SYSDATE, -13), 'MM') THEN line_qnty ELSE 0 END AS qnty_mnth_8, CASE WHEN TRUNC(EVNT_DATE, 'MM') = TRUNC(ADD_MONTHS(SYSDATE, -12), 'MM') THEN line_qnty ELSE 0 END AS qnty_mnth_9, CASE WHEN TRUNC(EVNT_DATE, 'MM') = TRUNC(ADD_MONTHS(SYSDATE, -2), 'MM') THEN line_qnty ELSE 0 END AS qnty_mnth_10, CASE WHEN TRUNC(EVNT_DATE, 'MM') = TRUNC(ADD_MONTHS(SYSDATE, -1), 'MM') THEN line_qnty ELSE 0 END AS qnty_mnth_11, CASE WHEN TRUNC(EVNT_DATE, 'MM') = TRUNC(ADD_MONTHS(SYSDATE, 0), 'MM') THEN line_qnty ELSE 0 END AS qnty_mnth_12 from (select (LGSTC_ACTL_TRNS.QNTY_1 * LGSTC_ACTL_TRNS.LINE_SIGN * -1) as line_qnty, LGSTC_ACTL_TRNS.LINE_TRNS_STAT, LGSTC_ACTL_TRNS.LINE_SIGN, LGSTC_ACTL_TRNS.QNTY_1, LGSTC_ACTL_TRNS.PART_CODE, LGSTC_ACTL_TRNS.PRMY_TRNS_CLSS, LGSTC_ACTL_TRNS.DOC_NBR, PARTS.PART_SHRT_NAME, PARTS.PART_LONG_NAME, LGSTC_ACTL_DOCS.EVNT_DATE from DBTRANS.LGSTC_ACTL_TRNS LGSTC_ACTL_TRNS inner join DBTRANS.PARTS PARTS on LGSTC_ACTL_TRNS.FIRM_CODE = PARTS.FIRM_CODE and LGSTC_ACTL_TRNS.PART_CODE = PARTS.PART_CODE left join DBTRANS.LGSTC_ACTL_DOCS LGSTC_ACTL_DOCS on LGSTC_ACTL_TRNS.FIRM_CODE = LGSTC_ACTL_DOCS.FIRM_CODE and LGSTC_ACTL_TRNS.PRMY_TRNS_CLSS = LGSTC_ACTL_DOCS.PRMY_TRNS_CLSS and LGSTC_ACTL_TRNS.DOC_NBR = LGSTC_ACTL_DOCS.DOC_NBR where LGSTC_ACTL_TRNS.FIRM_CODE = 21 and (LGSTC_ACTL_TRNS.LINE_TRNS_STAT >= 20 and LGSTC_ACTL_TRNS.LINE_TRNS_STAT <= 40) and LGSTC_ACTL_DOCS.CUST_CODE = '1' and (LGSTC_ACTL_DOCS.PRMY_TRNS_CLSS = 323 or LGSTC_ACTL_DOCS.PRMY_TRNS_CLSS = 325) and (LGSTC_ACTL_DOCS.TRNS_STAT >= 20 and LGSTC_ACTL_DOCS.TRNS_STAT <= 40) and LGSTC_ACTL_DOCS.EVNT_DATE >= TO_DATE('01-01-2007 00:00:00', 'DD-MM-YYYY HH24:MI:SS') and (LGSTC_ACTL_DOCS.FREE_FLD_1 = '1' or LGSTC_ACTL_DOCS.FREE_FLD_1 = '2')) ) t group by part_code,part_shrt_name;


select TRUNC(ADD_MONTHS(SYSDATE, -24), 'YYYY') from dual;
